import{_ as e,c as l,o as i,ah as r}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"山雷頤","description":"周易折中 - 山雷頤","frontmatter":{"title":"山雷頤","description":"周易折中 - 山雷頤"},"headers":[],"relativePath":"classics/zhezhong/033.md","filePath":"classics/zhezhong/033.md"}'),h={name:"classics/zhezhong/033.md"};function p(n,a,d,t,s,o){return i(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="山雷頤" tabindex="-1">山雷頤 <a class="header-anchor" href="#山雷頤" aria-label="Permalink to “山雷頤”">​</a></h1><h3 id="程傳" tabindex="-1">程傳 <a class="header-anchor" href="#程傳" aria-label="Permalink to “程傳”">​</a></h3><p>頤序卦：物畜然後可養，故受之以頤。夫物既畜聚，則必有以養之，無養則不能存息。頤所以次大畜也。卦上艮下震，上下二陽爻中含四陰，上止而下動，外實而中虛，人頤頷之象也。頤，養也。人口所以飲食養人之身，故名為頤。聖人設卦推養之義，大至於天地養育萬物，聖人養賢以及萬民，與人之養生、養形、養德、養人，皆頤養之道也。動息節宣以養生也，飲食衣服以養形也，威儀行義以養德也，推己及物以養人也。</p><p>頤：貞吉，觀頤，自求口實</p><h3 id="本義" tabindex="-1">本義 <a class="header-anchor" href="#本義" aria-label="Permalink to “本義”">​</a></h3><p>頤，口旁也，口食物以自養，故為養義。為卦上下二陽內含四陰，外實內虛，上止下動，為頤之象。養之義貞吉者，佔者得正則吉。觀頤，謂觀其所養之道；自求口實，謂觀其所以養身之術，皆得正則吉也。</p><h3 id="程傳-1" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-1" aria-label="Permalink to “程傳”">​</a></h3><p>頤之道，以正則吉也。人之養身、養德、養人、養於人，皆以正道則吉也。天地造化，養育萬物，各得其宜者，亦正而已矣。觀頤自求口實，觀人之所頤與其自求口實之道，則善惡吉凶可見矣。</p><h3 id="集說" tabindex="-1">集說 <a class="header-anchor" href="#集說" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類雲 ：養須是正則吉，觀頤是觀其養德正不正，自求口實是觀其養身正不正。未說到養人處。</p></li><li><p>林氏希元曰 ：人之所養有二，一是養性，一是養身，二者皆不可不正。觀其所養之道，如大學聖賢之道正也，異端小道則不正矣。又必自求其口實，如重道義而略口體正也，急口體而輕道義則不正矣。皆正則吉，不正則兇。</p></li><li><p>陳氏琛曰 ：集義以養其氣，寡慾以養其心，守聖道而不溺於虛無，崇聖學而不流於術數，則所以養德者正矣。窮而不屑於呼蹴，達而不至於素餐，不以貧賤飢渴害其心，不以聲色臭味汩其性，則所以養身者正矣。</p></li><li><p>陸氏銓曰 ：觀頤即考其善不善，自求口實即於己取之而已矣。</p></li></ul><h3 id="案" tabindex="-1">案 <a class="header-anchor" href="#案" aria-label="Permalink to “案”">​</a></h3><p>陸氏說與傳義異，蓋雲觀其所養者以自求養而已。如所養者德乎，則當自求其所以養德之道；如所養者身乎，則當自求其所以養身之方。與夫子《彖傳》語意尤合也。</p><p>象曰：山下有雷，頤；君子以愼言語，節飲食</p><h3 id="本義-1" tabindex="-1">本義 <a class="header-anchor" href="#本義-1" aria-label="Permalink to “本義”">​</a></h3><p>二者，養德養身之切務。</p><h3 id="程傳-2" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-2" aria-label="Permalink to “程傳”">​</a></h3><p>以二體言之，山下有雷，雷震於山下，山之生物皆動其根荄，發其萌芽，為養之象。以上下之義言之，艮止而震動，上止下動，頤頷之象。以卦形言之，上下二陽中含四陰，外實中虛，頤口之象。口所以養身也，故君子觀其象以養其身，愼言語以養其德，節飲食以養其體。不唯就口取養義，事之至近而所繫至大者，莫過於言語飲食也。在身為言語，於天下則凡命令政教出於身者皆是，愼之則必當而無失。在身為飲食，於天下則凡貨資財用養於人者皆是，節之則適宜而無傷。推養之道，養德養天下莫不然也。</p><h3 id="集說-1" tabindex="-1">集說 <a class="header-anchor" href="#集說-1" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>朱子語類 ：或雲“諺有‘禍從口出，病從口入’，甚好。曰：此語前輩曾用以解頤之象。愼言語，節飲食。</p></li><li><p>馮氏椅曰 ：“法雷之動以愼其所出，法山之止以節其所入。”</p></li><li><p>趙氏汝梅曰 ：“雷之聲為言語，山之養為飲食。言語飲食出入乎頤者也。”</p></li><li><p>俞氏琰曰 ：“頤乃口頰之象，故取其切於頤者言之曰‘愼言語，節飲食’。充此言語之類，則凡號令政教之出於己者，皆所當愼而不可悖出。充此飲食之類，則凡貨財賦稅之入於上者，皆所當節而不可悖入。”</p></li></ul><p>彖曰：頤貞吉，養正則吉也；觀頤，觀其所養也；自求口實，觀其自養也</p><h3 id="本義-2" tabindex="-1">本義 <a class="header-anchor" href="#本義-2" aria-label="Permalink to “本義”">​</a></h3><p>釋卦辭。</p><h3 id="程傳-3" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-3" aria-label="Permalink to “程傳”">​</a></h3><p>貞吉，所養者正則吉也。所養，謂所養之人與養之之道。自求口實，謂其自求養身之道，皆以正則吉也。</p><h3 id="集說-2" tabindex="-1">集說 <a class="header-anchor" href="#集說-2" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>李氏舜臣曰：古之觀人，每每觀其所養。而所養之大小，則必以其所自養者觀之。夫重道義之養而略口體，此養之大者也；急口體之養而輕道義，此養之小者也。養其大體則為大人，養其小體則為小人。天之賦予，初無小大之別，而人之所養各殊，則其所成就者亦異。</p></li><li><p>谷氏家傑曰：觀頤者，當於所養觀之，又當於所養中自養處觀之。</p></li></ul><h3 id="案-1" tabindex="-1">案 <a class="header-anchor" href="#案-1" aria-label="Permalink to “案”">​</a></h3><p>李氏、谷氏說皆得孟子考其善不善之意。</p><p>天地養萬物，聖人養賢以及萬民，頤之時大矣哉</p><h3 id="本義-3" tabindex="-1">本義 <a class="header-anchor" href="#本義-3" aria-label="Permalink to “本義”">​</a></h3><p>極言養道而贊之。</p><h3 id="程傳-4" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-4" aria-label="Permalink to “程傳”">​</a></h3><p>聖人極言頤之道而贊其大。天地之道，則養育萬物。養育萬物之道，正而已矣。聖人作養賢才，與之共天位，使之食天祿，俾施澤於天下，養賢以及萬民也。養賢所以養萬民也。夫天地之中，品物之眾，非養則不生。聖人裁成天地之道，輔相天地之宜，以養天下，至於鳥獸草木，皆有養之之政。其道配天地，故夫子推頤之道，贊天地與聖人之功曰：“頤之時大矣哉！”或雲義，或雲用，或止雲時，以其大者也。萬物之生與養，時為大，故云時。</p><h3 id="集說-3" tabindex="-1">集說 <a class="header-anchor" href="#集說-3" aria-label="Permalink to “集說”">​</a></h3><ul><li>趙氏汝梅曰：聖人之於萬民，豈能家與之粟而人與之衣？其急先務者，亦曰養賢而已。賢得所養，則仁恩自及於百姓矣。</li></ul><h3 id="案-2" tabindex="-1">案 <a class="header-anchor" href="#案-2" aria-label="Permalink to “案”">​</a></h3><p>卦有曰尚賢、養賢者，皆是六五上九相遇，如大有、大畜、頤、鼎等卦。此卦頤為養義，而六五又賴上九之養以養人，故曰“聖人養賢以及萬民”也。</p><p>初九：舍爾靈龜，觀我朵頤，兇</p><h3 id="本義-4" tabindex="-1">本義 <a class="header-anchor" href="#本義-4" aria-label="Permalink to “本義”">​</a></h3><p>靈龜，不食之物。朵，垂也。朵頤，欲食之貌。初九陽剛在下，足以不食，乃上應六四之陰而動於欲，兇之道也。故其象佔如此。</p><h3 id="程傳-5" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-5" aria-label="Permalink to “程傳”">​</a></h3><p>蒙之初六，蒙者也，爻乃主發矇而言。頤之初九，亦假外而言爾。謂初也，舎爾之靈龜，乃觀我而朵頤。我對爾而設。初之所以朵頤者，四也。然非四謂之也，假設之辭耳。九陽體剛明，其才智足以養正者也。龜能咽息不食，靈龜喻其明智而可以不求養於外也。才雖如是，然以陽居動體，而在頤之時，求頤人所欲也。上應於四，不能自守，志在上行，說所欲而朵頤者也。心既動，則其自失必矣。迷欲而失己，以陽而從陰，則何所不至，是以兇也。朵頤為朵，動其頤頷，人見食而欲之，則動頤垂涎，故以為象。</p><h3 id="集說-4" tabindex="-1">集說 <a class="header-anchor" href="#集說-4" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：朵頤者，嚼也。以陽處下而為動始，不能令物由己養，動而求養者也。夫安身莫若不競，修己莫若自保。守道則福至，求祿則辱來。居養賢之世，不能貞其所履以全其德，而舎其靈龜之明兆，羨我朵頤而躁求，兇莫甚焉。</p></li><li><p>蘇氏軾曰 ：養人者陽也，養於人者陰也。君子在上，足以養人；在下，足以自養。初九以一陽而伏於四陰之下，其德足以自養而無待於物者如龜也。不能守之而觀於四，見其可欲，朵頤而慕之，為陰之所致也，故兇。</p></li><li><p>鄭氏汝諧曰 ：頤之上體皆吉，而下體皆兇。上體止也，下體動也。在上而止，養人者也；在下而動，求養於人者也。動而求養於人者，必累於口體之養，故雖以初之剛陽，未免於動其欲而觀朵頤也。</p></li><li><p>何氏楷曰 ：初與上陽剛之德同而吉凶不同者，初為動之主，上為止之主。養道宜靜，故也。</p></li></ul><h3 id="附錄" tabindex="-1">附錄 <a class="header-anchor" href="#附錄" aria-label="Permalink to “附錄”">​</a></h3><ul><li>項氏安世曰 ：頤卦惟有二陽，上九在上，謂之由頤，固為所養之主。初九在下，亦足為自養之賢。靈龜伏息而在下，初九之象也。朵頤在上而下垂，上九之象也。上九為卦之主，故稱我。群陰從我而求養，固其所也。初九本無所求，乃亦仰而觀我，有靈而不自保，有貴而不自珍，宜其兇也。初九本靈本貴，聖人以其為動之主，居養之初，故深戒之以明自養之道。</li></ul><h3 id="案-3" tabindex="-1">案 <a class="header-anchor" href="#案-3" aria-label="Permalink to “案”">​</a></h3><p>項氏以“觀我朵頤”為上九亦備一說。</p><p>象曰：觀我朵頤，亦不足貴也</p><h3 id="程傳-6" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-6" aria-label="Permalink to “程傳”">​</a></h3><p>九動體朵頤，謂其說陰而志動，既為欲所動，則雖有剛健明智之才，終必自失，故其才亦不足貴也。人之貴乎剛者，為其能立而不屈於欲也；貴乎明者，為其能照而不失於正也。既惑所欲而失其正，何剛明之有為可賤也。</p><h3 id="集說-5" tabindex="-1">集說 <a class="header-anchor" href="#集說-5" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>楊氏簡曰 ：明其本有良貴，今觀夫朵頤，則失其所謂貴矣。</p></li><li><p>俞氏琰曰 ：孟子云：“養其大體為大人，養其小體為小人。”又云：“飲食之人則人賤之矣。”今初九陽德之大本，有可貴之質，乃內舍其大，而外觀其小，豈不為人所賤？故曰“亦不足貴也”。</p></li></ul><p>六二：顛頤拂經於丘頤，徵兇</p><h3 id="本義-5" tabindex="-1">本義 <a class="header-anchor" href="#本義-5" aria-label="Permalink to “本義”">​</a></h3><p>求養於初，則顛倒而違於常理；求養於上，則往而得兇。丘，土之高者，上之象也。</p><h3 id="程傳-7" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-7" aria-label="Permalink to “程傳”">​</a></h3><p>女不能自處，必從男；陰不能獨立，必從陽。二陰柔不能自養，待養於人者也。天子養天下，諸侯養一國，臣食君上之祿，民賴司牧之養，皆以上養下，理之正也。二既不能自養，必求養於剛陽。若反下求於初，則為顛倒，故云顛頤。顛則拂違經常，不可行也。若求養於丘，則往必有兇。丘在外而高之物，謂上九也。卦止二陽，既不可顛頤於初，若求頤於上九，往則有兇。在頤之時，相應則相養者也。上非其應而往求養，非道妄動，是以兇也。顛頤則拂經，不獲其養爾，妄求於上，往則得兇也。今有人才不足以自養，見在上者𫝑力足以養人，非其族類，妄往求之，取辱得兇必矣。六二中正在他卦多吉而兇，何也？曰：時然也。陰柔既不足以自養，初上二爻皆非其與，故往求則悖理而得兇也。</p><h3 id="集說-6" tabindex="-1">集說 <a class="header-anchor" href="#集說-6" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>項氏安世曰 ：二五得位得中，而不能自養，反由頤於無位之爻，與常經相悖，故皆為拂經。上艮體，故為於丘。</p></li><li><p>黃氏幹曰 ：頤之六爻，只是顛拂二字。求養於下則為顛，求養於上則為拂。六二比初而求上，故“顛頤”當為句，“拂經於丘頤”為句，“徵兇”則其佔辭也。六三拂頤，雖與上為正應，然是求於上以養己，故兇。六四顛頤，固與初為正應，然是賴初之養以養人，故雖顛而吉。六五拂經，是比於上，然是賴上九之養以養人，所以居貞而亦吉。</p></li></ul><h3 id="案-4" tabindex="-1">案 <a class="header-anchor" href="#案-4" aria-label="Permalink to “案”">​</a></h3><p>項氏、黃氏說深得文意，可從。本義雖從程傳以“徵兇”屬之“丘頤”，然至其解《象傳》“六二徵兇，行失類也”，則曰“初上皆非其類也”，則亦以“徵兇”總承兩義矣。</p><p>象曰：六二徵兇，行失類也</p><h3 id="本義-6" tabindex="-1">本義 <a class="header-anchor" href="#本義-6" aria-label="Permalink to “本義”">​</a></h3><p>初上皆非其類也。</p><h3 id="程傳-8" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-8" aria-label="Permalink to “程傳”">​</a></h3><p>徵而從上則兇者，非其類故也。往求而失其類，得兇宜矣。行，往也。</p><p>六三：拂頤貞兇，十年勿用，無攸利</p><h3 id="本義-7" tabindex="-1">本義 <a class="header-anchor" href="#本義-7" aria-label="Permalink to “本義”">​</a></h3><p>陰柔不中正，以處動極，拂於頤矣。既拂於頤，雖正亦兇，故其象佔如此。</p><h3 id="程傳-9" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-9" aria-label="Permalink to “程傳”">​</a></h3><p>頤之道，惟正則吉。三以陰柔之質而處不中正，又在動之極，是柔邪不正而動者也。其養如此，拂違於頤之正道，是以兇也。得頤之正則所養皆吉，求養養人則合於義，自養則成其德。三乃拂違正道，故戒以“十年勿用”，十數之終，謂終不可用，無所往而利也。</p><h3 id="集說-7" tabindex="-1">集說 <a class="header-anchor" href="#集說-7" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>張子曰 ：履邪好動，系說於上，不但拂頤之經而已，害頤之正莫甚焉，故兇。</p></li><li><p>楊氏時曰 ：頤正則吉，六三不中正而居動之極，拂頤之正也。十年勿用，則終不可用矣，何利之有？</p></li><li><p>鄭氏汝諧曰 ：三應於上，若得所養而兇莫甚於三，蓋不中不正而居動之極，所以求養於人者必無所不至，是謂拂於頤之正，兇之道也。十年勿用，無攸利，戒之也。因其多欲妄動，示之以自反之理，作易之本意也。</p></li></ul><p>象曰：十年勿用，道大悖也</p><h3 id="程傳-10" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-10" aria-label="Permalink to “程傳”">​</a></h3><p>所以戒終不可用，以其所由之道大悖義理也。</p><h3 id="集說-8" tabindex="-1">集說 <a class="header-anchor" href="#集說-8" aria-label="Permalink to “集說”">​</a></h3><ul><li>項氏安世曰 ：“拂頤貞”三字當連讀。頤之卦辭曰：“頤貞吉。”三之爻辭曰：“拂頤貞兇。”卦中惟此一爻與卦義相反，故曰“道大悖也”。</li></ul><p>六四：顛頤吉，虎視眈眈，其欲逐逐，無咎</p><h3 id="本義-8" tabindex="-1">本義 <a class="header-anchor" href="#本義-8" aria-label="Permalink to “本義”">​</a></h3><p>柔居上而得正，所應又正，而賴其養以施於下，故雖顛而吉。虎視眈眈，下而專也；其欲逐逐，求而繼也。又能如是，則無咎矣。</p><h3 id="程傳-11" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-11" aria-label="Permalink to “程傳”">​</a></h3><p>四在人上，大臣之位。六以陰居之，陰柔不足以自養，況養天下乎？初九以剛陽居下，在下之賢也，與四為應。四又柔順而正，是能順於初，賴初之養也。以上養下則為順，今反求下之養，顛倒也，故曰顛頤。然已不勝其任，求在下之賢而順從之以濟其事，則天下得其養而已，無曠敗之咎，故為吉也。夫居上位者，必有才德威望，為下民所尊畏，則事行而眾心服從。若或下易其上，則政出而人違，刑施而怨起，輕於陵犯，亂之由也。六四雖能順從剛陽，不廢厥職，然質本陰柔，賴人以濟。人之所輕，故必養其威嚴。耽耽然如虎視，則能重其體貌，下不敢易。又從於人者，必有常。若間或無繼，則其政敗矣。其欲謂所須用者，必逐逐相繼而不乏，則其事可濟。若取於人而無繼，則困窮矣。既有威嚴，又所施不窮，故能無咎也。二顛頤則拂經，四則吉，何也？曰：二在上而反求養於下，下非其應類，故為拂經；四則居上位以貴下賤，使在下之賢由己以行其道，上下之志相應而施於民，何吉如之？自三以下養口體者也，四以上養德義者也。以君而資養於臣，以上位而賴養於下，皆養德也。</p><h3 id="集說-9" tabindex="-1">集說 <a class="header-anchor" href="#集說-9" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>蘇氏軾曰 ：自初而言之，則初之見養於四為兇；自四言之，則四之得養初九為吉。</p></li><li><p>遊氏酢曰 ：以上養下，頤之正也。若在上而反資養於下，則於頤為倒置矣。此二與四所以俱為顛頤也。然二之志在物，而四之志在道，故四顛頤而吉，而二則徵兇也。</p></li><li><p>朱子語類問音辯載馬氏曰 ：眈眈，虎下視貌，則當為下而專矣。又問其欲逐逐如何，曰：求於下以養人，必當繼繼求之，不厭乎數，然後可以養人而不窮。</p></li><li><p>呉氏澄曰 ：自養於內者莫如龜，求養於外者莫如虎。故頤之初九、六四取二物為象。四之於初，其下賢求益之心必如虎之視下求食而後可。其視下也專一而不他，其欲食也繼續而不歇，如是則於人不貳，於己不自足，乃得居上求下之道。</p></li><li><p>林氏希元曰 ：苟下賢之心不專，則賢者不樂告以善道；求益之心不繼，則才有所得而遽自足。</p></li></ul><p>象曰：顚頤之吉，上施光也</p><h3 id="程傳-12" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-12" aria-label="Permalink to “程傳”">​</a></h3><p>顚倒求養而所以吉者，蓋得剛陽之應以濟其事，致己居上之德施光明被於天下，吉孰大焉。</p><h3 id="集說-10" tabindex="-1">集說 <a class="header-anchor" href="#集說-10" aria-label="Permalink to “集說”">​</a></h3><ul><li>谷氏家傑曰 ：養逮於下，則上施光，是養賢及民也。</li></ul><p>六五：拂經居貞吉，不可涉大川</p><h3 id="本義-9" tabindex="-1">本義 <a class="header-anchor" href="#本義-9" aria-label="Permalink to “本義”">​</a></h3><p>六五陰柔不正，居尊位而不能養人，反賴上九之養，故其象佔如此。</p><h3 id="程傳-13" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-13" aria-label="Permalink to “程傳”">​</a></h3><p>六五，頤之時，居君位，養天下者也。然其陰柔之質，才不足以養天下。上有剛陽之賢，故順從之，賴其養己以濟天下。君者，養人者也，反賴人之養，是違拂於經常。既以己之不足而順從於賢師傅上，師傅之位也，必居守貞固，篤於委信，則能輔翼其身，澤及天下，故吉也。陰柔之質，無貞剛之性，故戒以能居貞則吉。以陰柔之才，雖倚賴剛質，能持循於平時，不可處艱難變故之際，故云“不可涉大川”也。以成王之才，不至甚柔弱也，當管蔡之亂，幾不保於周公，況其下者乎？故書曰：“王亦未敢誚公。”賴二公得終信，故艱險之際，非剛明之主不可恃也。不得已而濟艱險者，則有矣，發此義者，所以深戒於為君也。於上九，則據為臣致身盡忠之道言，故不同也。</p><h3 id="集說-11" tabindex="-1">集說 <a class="header-anchor" href="#集說-11" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>丘氏富國曰 ：豫五不言豫，以豫由乎四也；頤五不言頤，以頤由乎上也。</p></li><li><p>林氏希元曰 ：不能養人而反賴上九以養於人，故其象為拂經，言反常也。然在己不能養人而賴賢者以養，亦正道也，故居貞而吉。若不用人而自用，則任大責重，終不能勝，如涉大川終不能濟，故不可。</p></li></ul><p>象曰：居貞之吉，順以從上也</p><h3 id="程傳-14" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-14" aria-label="Permalink to “程傳”">​</a></h3><p>居貞之吉者，謂能堅固順從於上九之賢以養天下也。</p><h3 id="集說-12" tabindex="-1">集說 <a class="header-anchor" href="#集說-12" aria-label="Permalink to “集說”">​</a></h3><ul><li>張氏清子曰 ：五能柔順以從上九之賢，賴之以養天下，真聖人養賢以及萬民之事也。</li></ul><p>上九：由頤厲吉，利涉大川</p><h3 id="本義-10" tabindex="-1">本義 <a class="header-anchor" href="#本義-10" aria-label="Permalink to “本義”">​</a></h3><p>六五賴上九之養以養人，是物由上九以養也。位高任重，故厲而吉。陽剛在上，故利涉川。</p><h3 id="程傳-15" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-15" aria-label="Permalink to “程傳”">​</a></h3><p>上九以剛陽之德，居師傅之任，六五之君柔順而從於己，賴己之養，是當天下之任，天下由之以養也。以人臣而當是任，必常懷危厲，則吉也。如伊尹、周公何嘗不憂勤兢畏，故得終吉。夫以君之才不足而倚賴於己，身當天下大任，宜竭其才力，濟天下之艱危，成天下之治安，故曰“利涉大川”。得君如此之專，受任如此之重，苟不濟天下艱危，何足稱委遇而謂之賢乎？當盡誠竭力而不顧慮，然惕厲則不可忘也。</p><h3 id="集說-13" tabindex="-1">集說 <a class="header-anchor" href="#集說-13" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏弼曰 ：以陽處上而履四陰，陰不能獨為主，必宗於陽也，故莫不由之以得其養。</p></li><li><p>李氏舜臣曰 ：豫九四曰“由豫”者，即由頤之謂也。“由豫”在四，猶下於五也，而已有可疑之跡；“由頤”在上，則過中而嫌於不安，故厲。</p></li><li><p>丘氏富國曰 ：陽實陰虛，實者養人，虛者求人之養。故四陰皆求養於陽者。然養之權在上，是二陽爻又以上為主，而初陽亦求養者也，故直於上九一爻曰“由頤”焉。</p></li></ul><p>象曰：由頤厲吉，大有慶也</p><h3 id="程傳-16" tabindex="-1">程傳 <a class="header-anchor" href="#程傳-16" aria-label="Permalink to “程傳”">​</a></h3><p>若上九之當大任，如是能兢畏，如是天下被其德澤，是大有福慶也。</p><h3 id="集說-14" tabindex="-1">集說 <a class="header-anchor" href="#集說-14" aria-label="Permalink to “集說”">​</a></h3><ul><li><p>王氏宗傳曰 ：豫之九四，天下由之以豫，故曰“大有得”。頤之上九，天下由之以頤，故曰“大有慶”。</p></li><li><p>項氏安世曰 ：六五、上九二爻皆當以小象解之。六五之“居貞”，非自守也，貞於從上也，故曰“居貞之吉，順以從上也”。上九之“厲吉”，非能自吉也，得六五之委任而吉也，故曰“由頤厲吉，大有慶也”。</p></li></ul><p>總論</p><p>呉氏曰 ：慎曰養之為道，以養人為公，養己為私。自養之道，以養德為大，養體為小。艮三爻皆養人者，震三爻皆養己者。初九、六二、六三皆自養口體，私而小者也；六四、六五、上九皆養其德以養人，公而大者也。公而大者吉，得頤之正也；私而小者兇，失頤之貞也。可不觀頤而自求其正耶？</p>',117)])])}const m=e(h,[["render",p]]);export{b as __pageData,m as default};
